INSERT INTO artigos (slug,status,tipo,titulo,titulo_original,autor,autor_citacao,afiliacao,tradutor,periodico,volume,numero,ano,mes,paginas_original,editora_original,url_original,area,tema,tema_en,resumo,resumo_en,resumo_editorial,palavras_chave,direitos,pdf_url,pdf_paginas,capa_url,publicado_em) VALUES
('collins-bob-jones-profetas-kansas-city','publicado','traducao','Bob Jones e os Profetas de Kansas City: o modelo por trás do IHOPKC','Bob Jones and the Kansas City Prophets: The Blueprint Behind IHOPKC','John Collins','COLLINS, John','William Branham Historical Research','Gabriel Cantarino','William Branham Historical Research',NULL,NULL,'2025','jul.',NULL,'william-branham.org','https://william-branham.org/research/bob_jones','História','Profetas de Kansas City · Bob Jones','Kansas City Prophets · Bob Jones','Bob Jones ascendeu no meio dos Profetas de Kansas City e ajudou a moldar o IHOPKC ao promover testemunhos dramáticos, visões em “technicolor”, narrativas de visitações angélicas e afirmações escatológicas que ecoavam padrões anteriores da Chuva Serôdia (Latter Rain) associados a William Branham. O fio condutor é que fracassos proféticos repetidos e cronologias cada vez mais voltadas ao domínio foram tratados como legitimadores da “revelação”, criando um modelo de autoridade profética carismática moderna que continuou a influenciar a Nova Reforma Apostólica e movimentos correlatos.','Bob Jones rose within the Kansas City Prophets and helped shape IHOPKC by promoting dramatic testimony, “technicolor” visions, angel-visit narratives, and end-times claims that echoed earlier Latter Rain patterns associated with William Branham. The common thread is that repeated prophetic failures and increasingly dominion-oriented timelines were treated as validating “revelation,” creating a model of modern charismatic prophetic authority that went on to shape the New Apostolic Reformation and related movements.',0,'["Bob Jones", "Profetas de Kansas City", "IHOPKC", "Mike Bickle", "Chuva Serôdia", "William Branham", "Nova Reforma Apostólica", "falsa profecia"]','Os direitos do texto original pertencem a John Collins (William Branham Historical Research). Tradução para o português © 2026 Gabriel Cantarino / The Prophetic Voices, publicada para fins de estudo, sem fins lucrativos. O texto será retirado a pedido do detentor dos direitos.','/artigos/collins-2025-bob-jones-profetas-kansas-city.pdf',9,'/artigos/collins-2025-bob-jones-profetas-kansas-city-capa.jpg','2026-11-19 17:30:00'),
('gruen-praticas-ensinos-kansas-city-fellowship','publicado','traducao','Documentação das práticas e ensinos aberrantes da Kansas City Fellowship','Documentation of the Aberrant Practices and Teachings of Kansas City Fellowship','Ernest Gruen e equipe','GRUEN, Ernest','Full Faith Church of Love, Shawnee (Kansas)','Gabriel Cantarino','Documento eclesiástico (fonte primária)',NULL,NULL,'1990',NULL,NULL,'Full Faith Church of Love; edição eletrônica de Banner Ministries (Tricia Tillin)','http://www.banner.org.uk','História','Kansas City Fellowship · Mike Bickle','Kansas City Fellowship · Mike Bickle','Fonte primária de 1990: a carta aberta e o dossiê com que o pastor Ernest Gruen, da Full Faith Church of Love (Shawnee, Kansas), acusou Mike Bickle e a Kansas City Fellowship de práticas e ensinos aberrantes. A partir de transcrições de mensagens gravadas, testemunhos escritos de pastores e ex-membros e das experiências da própria equipe, o documento reúne as profecias, visões e ensinos de Bickle, Bob Jones e outros líderes que Gruen considerava desvios do cristianismo bíblico. É um texto polêmico e advocatício, não um relato neutro; está aqui como documento para o estudo histórico do movimento profético carismático e da controvérsia que levou John Wimber a assumir a supervisão da igreja.','A primary source from 1990: the open letter and dossier in which Pastor Ernest Gruen of Full Faith Church of Love (Shawnee, Kansas) charged Mike Bickle and Kansas City Fellowship with aberrant practices and teachings. Drawing on transcripts of recorded messages, written testimony from pastors and former members, and his team’s own experience, the document gathers the prophecies, visions and teachings of Bickle, Bob Jones and other leaders that Gruen regarded as departures from biblical Christianity. It is a polemical, advocacy text, not a neutral account; it is presented here for the historical study of the charismatic prophetic movement and of the controversy that led John Wimber to take over oversight of the church.',1,'["Ernest Gruen", "Kansas City Fellowship", "Mike Bickle", "Bob Jones", "Profetas de Kansas City", "John Wimber", "falsa profecia", "fonte primária"]','Os direitos do texto original pertencem a Ernest Gruen e à Full Faith Church of Love; a edição eletrônica é da Banner Ministries. Tradução para o português © 2026 Gabriel Cantarino / The Prophetic Voices, publicada para fins de estudo, sem fins lucrativos. O texto será retirado a pedido do detentor dos direitos.','/artigos/gruen-1990-kansas-city-fellowship.pdf',126,'/artigos/gruen-1990-kansas-city-fellowship-capa.jpg','2026-11-19 17:30:00'),
('documentacao-disciplina-bob-jones-1991','publicado','traducao','Documentação da disciplina de Bob Jones (1991)','Documentation of the discipline of Bob Jones (1991)','Metro Vineyard Fellowship e Association of Vineyard Churches','METRO VINEYARD FELLOWSHIP','Kansas City (Missouri)','Gabriel Cantarino','National & International Religion Report e documentos da Vineyard',NULL,NULL,'1991',NULL,NULL,NULL,NULL,'História','Bob Jones · disciplina eclesiástica','Bob Jones · church discipline','Dossiê de fontes primárias sobre a disciplina de Bob Jones em 1991: a reportagem do National & International Religion Report (vol. 5, n. 25, 2 dez. 1991) sobre o “golpe” sofrido pelo movimento profético, e as cartas e declarações da Metro Vineyard Fellowship e da Association of Vineyard Churches que o removeram de todas as funções ministeriais. Os textos registram o motivo alegado (má conduta sexual e manipulação de membros por meio de profecias pessoais), o processo de restauração proposto e o pano de fundo da controvérsia com Ernest Gruen. Útil para estudar como o movimento tratou, em tempo real, a queda de um de seus profetas mais influentes.','A dossier of primary sources on the discipline of Bob Jones in 1991: the National & International Religion Report article (vol. 5, no. 25, Dec. 2, 1991) on the “blow” suffered by the prophetic movement, and the letters and statements from Metro Vineyard Fellowship and the Association of Vineyard Churches that removed him from all ministry roles. The texts record the stated reason (sexual misconduct and manipulation of members through personal prophecies), the proposed restoration process, and the background of the controversy with Ernest Gruen. Useful for studying how the movement dealt, in real time, with the fall of one of its most influential prophets.',1,'["Bob Jones", "disciplina", "Metro Vineyard", "John Wimber", "Mike Bickle", "Profetas de Kansas City", "prestação de contas", "fonte primária"]','Os direitos do texto original pertencem aos respectivos autores (National & International Religion Report; Metro Vineyard Fellowship; Association of Vineyard Churches). Tradução para o português © 2026 Gabriel Cantarino / The Prophetic Voices, publicada para fins de estudo, sem fins lucrativos. O texto será retirado a pedido do detentor dos direitos.','/artigos/disciplina-bob-jones-1991.pdf',25,'/artigos/disciplina-bob-jones-1991-capa.jpg','2026-11-19 17:30:00'),
('declaracao-padroes-profeticos','publicado','traducao','Declaração de Padrões Proféticos','Prophetic Standards Statement','Michael L. Brown, Joseph Mattera e signatários','BROWN, Michael L.; MATTERA, Joseph','AskDrBrown Ministries; U.S. Coalition of Apostolic Leaders','Gabriel Cantarino','Prophetic Standards Statement',NULL,NULL,'2021','abr.',NULL,'propheticstandards.com','https://propheticstandards.com/','Teologia bíblica','Ministério profético · prestação de contas','Prophetic ministry · accountability','Declaração redigida por Michael L. Brown e Joseph Mattera e assinada por dezenas de líderes pentecostais e carismáticos, publicada em abril de 2021 após as profecias fracassadas sobre a eleição americana de 2020. Afirma que o dom de profecia e o ministério do profeta são essenciais à edificação da Igreja e devem ser cultivados, e, ao mesmo tempo, estabelece diretrizes bíblicas para seu exercício: julgamento das palavras proféticas, submissão a supervisão, distinção entre profecia e opinião, reconhecimento público de erros e arrependimento quando uma palavra não se cumpre. Acompanha a lista dos signatários.','A statement drafted by Michael L. Brown and Joseph Mattera and signed by dozens of Pentecostal and charismatic leaders, released in April 2021 after the failed prophecies about the 2020 U.S. election. It affirms that the gift of prophecy and the ministry of the prophet are essential to building up the Church and should be cultivated, while setting biblical guidelines for their exercise: weighing prophetic words, submitting to oversight, distinguishing prophecy from opinion, and publicly acknowledging error and repenting when a word does not come to pass. The list of signatories is included.',1,'["profecia", "ministério profético", "prestação de contas", "Michael Brown", "Joseph Mattera", "1 Coríntios 14", "discernimento", "movimento carismático"]','Os direitos do texto original pertencem aos redatores e signatários da Prophetic Standards Statement. Tradução para o português © 2026 Gabriel Cantarino / The Prophetic Voices, publicada para fins de estudo, sem fins lucrativos. O texto será retirado a pedido do detentor dos direitos.','/artigos/declaracao-padroes-profeticos-2021.pdf',9,'/artigos/declaracao-padroes-profeticos-2021-capa.jpg','2026-11-19 17:30:00');
